insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-se-puede-cultivar-en-un-balcon-o-en-un-patio-pequeno','agricultura',array['ambiente']::text[],'¿Qué se puede cultivar en un balcón o en un patio pequeño?','Reúne qué plantas comestibles se adaptan a un balcón, una ventana o un patio chico, según el espacio, la luz y el tiempo que tienes, y conviértelo en una guía para quien quiere empezar.','Guía','2 semanas',12,array['Cultivos en poco espacio','Plantas comestibles']::text[],array['crear','resolver']::text[],'publicos',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura busqueda de informacion. comparacion de datos. diseno de una guia. escritura clara. guias agrarias publicas. hoja de calculo. un editor de documentos.',$a1agr${"id": "que-se-puede-cultivar-en-un-balcon-o-en-un-patio-pequeno", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué se puede cultivar en un balcón o en un patio pequeño?", "resumen": "Reúne qué plantas comestibles se adaptan a un balcón, una ventana o un patio chico, según el espacio, la luz y el tiempo que tienes, y conviértelo en una guía para quien quiere empezar.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 12, "etiquetas": ["Cultivos en poco espacio", "Plantas comestibles"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Mucha gente piensa que para tener un huerto hace falta un terreno grande. En realidad hay hierbas, hojas y algunas hortalizas que crecen bien en macetas, pero no todas sirven para cualquier espacio ni para cualquier cantidad de sol.", "Sin una guía clara, quien empieza suele elegir plantas muy exigentes, se frustra y abandona. Una buena selección inicial aumenta las posibilidades de éxito."], "desarrollar": ["Con guías públicas de instituciones agrarias y universidades, haz una lista de plantas comestibles aptas para macetas. Anota para cada una cuánta luz pide, qué tamaño de recipiente necesita, cada cuánto se riega y en cuánto tiempo se cosecha.", "Organiza la información en una tabla y luego en una guía de una página que ayude a elegir según el espacio disponible y las horas de sol. Incluye tres combinaciones recomendadas para quien empieza."], "ampliaciones": [{"titulo": "Por clima", "aporta": "adapta la guía a la costa, la sierra o la selva, según tu zona."}, {"titulo": "Ficha visual", "aporta": "diseña una ficha ilustrada para cada planta de la guía."}, {"titulo": "Prueba real", "aporta": "siembra dos de las plantas recomendadas y comprueba si la guía acertó."}], "objetivos": ["Reunir información confiable.", "Comparar las plantas según el espacio y la luz.", "Armar una guía de elección.", "Proponer combinaciones para empezar."], "habilidades": ["Búsqueda de información.", "Comparación de datos.", "Diseño de una guía.", "Escritura clara."], "herramientas": ["Guías agrarias públicas.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Aclara que es una guía general y que cada espacio tiene su propia luz y humedad.", "Prefiere plantas fáciles para quien empieza."], "otroSector": "La misma lógica sirve para elegir qué producir o vender según el espacio y los recursos de cualquier negocio pequeño."}$a1agr$::jsonb,8),
('un-huerto-en-macetas-diseno-paso-a-paso','agricultura',array['ambiente']::text[],'Un huerto en macetas: diseño paso a paso','Diseña, con medidas y un dibujo, un huerto en macetas para un espacio concreto: qué plantas pones, dónde va cada una, cómo las riegas y cuánto necesitas para empezar.','Plan','2 semanas',14,array['Diseño de huerto','Macetas']::text[],array['crear']::text[],'ficticios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura medicion y escala. planificacion. estimacion de costos. dibujo tecnico sencillo. papel y regla, o una herramienta de dibujo. hoja de calculo.',$a2agr${"id": "un-huerto-en-macetas-diseno-paso-a-paso", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Un huerto en macetas: diseño paso a paso", "resumen": "Diseña, con medidas y un dibujo, un huerto en macetas para un espacio concreto: qué plantas pones, dónde va cada una, cómo las riegas y cuánto necesitas para empezar.", "tipo": "Plan", "tiempo": "2 semanas", "horas": 14, "etiquetas": ["Diseño de huerto", "Macetas"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Un huerto en macetas parece sencillo, pero sin planificación se llena de macetas mal ubicadas, plantas que se tapan unas a otras y riegos desordenados. Planificar antes de comprar evita gastos y plantas perdidas.", "Diseñarlo en papel permite probar ideas sin riesgo y ajustar el huerto al espacio real."], "desarrollar": ["Elige un espacio, real o inventado, y mide su largo, ancho y las horas de sol que recibe. Dibuja un plano a escala con la ubicación de cada maceta y decide qué plantas van en cada una, cuidando que las más altas no tapen a las bajas.", "Haz una lista de materiales con cantidades, un esquema de riego semanal y un presupuesto con precios de ejemplo. Resume el diseño en un documento que otra persona podría seguir."], "ampliaciones": [{"titulo": "Varios escenarios", "aporta": "diseña el mismo huerto para un balcón, una terraza y una ventana."}, {"titulo": "Maqueta", "aporta": "construye una maqueta con cajas y papel para verificar el espacio."}, {"titulo": "Costos", "aporta": "compara el costo del huerto con reutilizar recipientes que ya tienes."}], "objetivos": ["Medir el espacio.", "Distribuir las plantas.", "Calcular materiales y costos.", "Documentar el diseño."], "habilidades": ["Medición y escala.", "Planificación.", "Estimación de costos.", "Dibujo técnico sencillo."], "herramientas": ["Papel y regla, o una herramienta de dibujo.", "Hoja de cálculo."], "lineamientos": ["Usa medidas y costos de ejemplo: no hace falta comprar nada para practicar el diseño.", "Aclara que el diseño es una propuesta y que la luz real puede cambiar el resultado."], "otroSector": "El mismo método de planificar con medidas y presupuesto sirve para distribuir una oficina, un taller o una tienda pequeña."}$a2agr$::jsonb,9),
('un-huerto-vertical-para-aprovechar-la-pared','agricultura',array['ciudades']::text[],'Un huerto vertical para aprovechar la pared','Diseña y arma un modelo de huerto vertical con materiales reutilizados, calcula cuántas plantas caben en un metro de pared y evalúa qué tan fácil es regarlo y cuidarlo.','Prototipo','3 semanas',22,array['Huerto vertical','Espacios reducidos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'arquitectura agronomia diseno ingenieria ambiental ingenieria civil educacion ingenieria mecatronica paisajismo diseno de prototipos. calculo sencillo de peso y volumen. pruebas. documentacion. materiales reutilizados. regla y papel. una camara.',$a3agr${"id": "un-huerto-vertical-para-aprovechar-la-pared", "area": "agricultura", "areas2": ["ciudades"], "titulo": "Un huerto vertical para aprovechar la pared", "resumen": "Diseña y arma un modelo de huerto vertical con materiales reutilizados, calcula cuántas plantas caben en un metro de pared y evalúa qué tan fácil es regarlo y cuidarlo.", "tipo": "Prototipo", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Huerto vertical", "Espacios reducidos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Arquitectura", "Agronomía", "Diseño", "Ingeniería Ambiental", "Ingeniería Civil", "Educación", "Ingeniería Mecatrónica", "Paisajismo"], "problema": ["Cuando no hay suelo ni espacio en el piso, la pared se vuelve una opción. Pero un huerto vertical mal pensado se cae, gotea sobre los vecinos o deja las plantas de arriba sin agua y las de abajo encharcadas.", "Resolver el soporte, el riego y el acceso antes de construir ahorra materiales y problemas."], "desarrollar": ["Dibuja tres diseños posibles, por ejemplo con botellas, cajones o tuberías, y compáralos según cuántas plantas caben, cuánto pesan, cómo se riegan y cuánto cuesta cada uno. Elige uno y construye un prototipo pequeño con materiales reutilizados.", "Prueba el modelo con agua para ver cómo escurre y dónde se acumula, y ajusta el diseño. Escribe una ficha con las medidas, los materiales y las lecciones aprendidas."], "ampliaciones": [{"titulo": "Riego en cascada", "aporta": "diseña un sistema donde el agua baje de nivel en nivel."}, {"titulo": "Peso", "aporta": "calcula cuánto pesa el huerto lleno y qué soporte necesita."}, {"titulo": "Instrucciones", "aporta": "crea una guía ilustrada para que otras personas lo armen."}], "objetivos": ["Comparar diseños.", "Construir un prototipo.", "Probar el riego.", "Documentar medidas y ajustes."], "habilidades": ["Diseño de prototipos.", "Cálculo sencillo de peso y volumen.", "Pruebas.", "Documentación."], "herramientas": ["Materiales reutilizados.", "Regla y papel.", "Una cámara."], "lineamientos": ["Verifica que el soporte aguante el peso y no cuelgues nada sobre pasillos o ventanas sin asegurarlo bien.", "Usa agua limpia y recipientes que no hayan contenido productos químicos.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches."], "otroSector": "El mismo ejercicio de aprovechar la pared sirve para diseñar estantes, almacenes y exhibidores en poco espacio."}$a3agr$::jsonb,10),
('importa-el-recipiente-macetas-botellas-y-cajones','agricultura',array['ambiente']::text[],'¿Importa el recipiente? Macetas, botellas y cajones','Cultiva la misma planta en recipientes distintos, como una maceta, una botella cortada y un cajón, y mide si el tamaño, el material y el drenaje cambian cómo crece.','Análisis','4 semanas',18,array['Recipientes','Crecimiento']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura diseno de experimentos simples. registro de datos. graficas. observacion. recipientes reutilizados. regla. hoja de calculo.',$a4agr${"id": "importa-el-recipiente-macetas-botellas-y-cajones", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Importa el recipiente? Macetas, botellas y cajones", "resumen": "Cultiva la misma planta en recipientes distintos, como una maceta, una botella cortada y un cajón, y mide si el tamaño, el material y el drenaje cambian cómo crece.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 18, "etiquetas": ["Recipientes", "Crecimiento"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Muchos huertos caseros usan lo que hay a mano: baldes, botellas, cajones. Se supone que todo recipiente sirve, pero el tamaño, el material y los huecos de drenaje pueden influir en las raíces y en la salud de la planta.", "Comparar de forma ordenada permite saber qué recipientes valen la pena y cuáles conviene evitar."], "desarrollar": ["Elige una planta de crecimiento rápido, como el rabanito o una hoja, y siémbrala en al menos tres recipientes distintos con el mismo sustrato, la misma luz y el mismo riego. Rotula cada recipiente.", "Cada pocos días mide la altura, cuenta las hojas y anota cómo escurre el agua. Presenta los resultados en un cuadro y una gráfica, y concluye qué recipiente funcionó mejor en tu caso."], "ampliaciones": [{"titulo": "Más variables", "aporta": "prueba también el color del recipiente y su tamaño."}, {"titulo": "Raíces", "aporta": "al final, observa cómo crecieron las raíces en cada uno."}, {"titulo": "Costo y duración", "aporta": "compara cuánto cuesta y cuánto dura cada recipiente."}], "objetivos": ["Preparar recipientes comparables.", "Medir el crecimiento.", "Analizar los resultados.", "Concluir con cautela."], "habilidades": ["Diseño de experimentos simples.", "Registro de datos.", "Gráficas.", "Observación."], "herramientas": ["Recipientes reutilizados.", "Regla.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa recipientes limpios y que no hayan contenido productos tóxicos.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro."], "otroSector": "El mismo método de comparar contenedores sirve para evaluar envases, cajas o paquetes en otros rubros."}$a4agr$::jsonb,11),
('que-sustrato-hace-crecer-mejor-las-hortalizas','agricultura',array['ambiente']::text[],'¿Qué sustrato hace crecer mejor las hortalizas?','Compara el crecimiento de una misma hortaliza en distintas mezclas de tierra, compost y otros materiales, y descubre qué combinación retiene mejor el agua y favorece el desarrollo.','Análisis','5 semanas',20,array['Sustratos','Hortalizas']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion control de variables. medicion. analisis de datos. comunicacion de resultados. tierra y materiales de mezcla. regla y balanza de cocina. hoja de calculo.',$a5agr${"id": "que-sustrato-hace-crecer-mejor-las-hortalizas", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué sustrato hace crecer mejor las hortalizas?", "resumen": "Compara el crecimiento de una misma hortaliza en distintas mezclas de tierra, compost y otros materiales, y descubre qué combinación retiene mejor el agua y favorece el desarrollo.", "tipo": "Análisis", "tiempo": "5 semanas", "horas": 20, "etiquetas": ["Sustratos", "Hortalizas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["La tierra de una maceta no es siempre igual: puede ser muy pesada, muy arenosa o pobre en nutrientes. Elegir mal el sustrato hace que el agua se encharque o se escurra demasiado rápido y que las plantas crezcan poco.", "Probar mezclas con medidas claras ayuda a entender qué necesita realmente una hortaliza."], "desarrollar": ["Prepara tres o cuatro mezclas, por ejemplo tierra sola, tierra con compost y tierra con arena, y siembra en cada una la misma hortaliza con la misma luz y riego. Anota la receta exacta de cada mezcla.", "Mide la altura, las hojas y qué tan rápido se seca cada sustrato. Compara en una tabla y explica cuál funcionó mejor y por qué crees que fue así."], "ampliaciones": [{"titulo": "Retención de agua", "aporta": "mide cuánta agua retiene cada mezcla con una prueba sencilla."}, {"titulo": "Costo", "aporta": "calcula cuánto cuesta preparar cada mezcla."}, {"titulo": "Receta recomendada", "aporta": "propón una mezcla para quien empieza."}], "objetivos": ["Preparar mezclas comparables.", "Medir el desarrollo de las plantas.", "Comparar retención de agua.", "Recomendar una mezcla."], "habilidades": ["Control de variables.", "Medición.", "Análisis de datos.", "Comunicación de resultados."], "herramientas": ["Tierra y materiales de mezcla.", "Regla y balanza de cocina.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa tierra limpia y evita sustratos de origen desconocido.", "Lávate las manos después de manipular tierra."], "otroSector": "El mismo método de probar mezclas sirve para comparar formulaciones de productos, materiales de construcción o recetas."}$a5agr$::jsonb,12),
('cuanta-luz-necesita-una-planta-comestible','agricultura',array[]::text[],'¿Cuánta luz necesita una planta comestible?','Cultiva la misma planta en lugares con distinta cantidad de luz, como una ventana soleada, una sombra parcial y un interior, y mide cómo cambia su crecimiento y su aspecto.','Análisis','4 semanas',16,array['Luz','Desarrollo de plantas']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura observacion sistematica. registro de datos. comparacion. fotografia de seguimiento. camara del celular. regla. hoja de calculo.',$a6agr${"id": "cuanta-luz-necesita-una-planta-comestible", "area": "agricultura", "areas2": [], "titulo": "¿Cuánta luz necesita una planta comestible?", "resumen": "Cultiva la misma planta en lugares con distinta cantidad de luz, como una ventana soleada, una sombra parcial y un interior, y mide cómo cambia su crecimiento y su aspecto.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 16, "etiquetas": ["Luz", "Desarrollo de plantas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Todas las plantas necesitan luz, pero no todas la misma cantidad. Ponerlas en un lugar con poca luz hace que se estiren, se debiliten o no produzcan, y no siempre se nota el problema hasta que es tarde.", "Medir la luz y el crecimiento permite elegir el mejor sitio para cada planta en casa."], "desarrollar": ["Siembra la misma planta en tres lugares con luz distinta y anota cuántas horas de sol directo recibe cada uno durante el día. Mantén igual el sustrato, el riego y el recipiente.", "Cada semana mide la altura, cuenta las hojas y toma una foto. Compara cómo crece cada planta, qué aspecto tiene y concluye cuál es la luz mínima que necesita para desarrollarse bien."], "ampliaciones": [{"titulo": "Medir la luz", "aporta": "usa una aplicación o una escala simple para comparar la luz de cada lugar."}, {"titulo": "Orientación", "aporta": "compara ventanas orientadas a distintos lados."}, {"titulo": "Guía de ubicación", "aporta": "crea una guía para colocar plantas según su necesidad de luz."}], "objetivos": ["Medir las horas de luz.", "Comparar el crecimiento.", "Observar señales de falta de luz.", "Elaborar una guía de ubicación."], "habilidades": ["Observación sistemática.", "Registro de datos.", "Comparación.", "Fotografía de seguimiento."], "herramientas": ["Cámara del celular.", "Regla.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro.", "No muevas las plantas durante el experimento: cambiar el sitio altera los resultados."], "otroSector": "El mismo método de medir un factor y ver su efecto sirve para evaluar iluminación en oficinas, aulas o tiendas."}$a6agr$::jsonb,13),
('que-metodo-de-germinacion-funciona-mejor','agricultura',array[]::text[],'¿Qué método de germinación funciona mejor?','Prueba distintas formas de hacer germinar la misma semilla, como algodón húmedo, papel toalla, tierra directa y remojo previo, y compara cuántas brotan y cuánto tardan.','Análisis','2 semanas',12,array['Germinación','Semillas']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura control de variables. conteo y porcentajes. graficas. paciencia y registro. semillas. algodon, papel y tierra. hoja de calculo.',$a7agr${"id": "que-metodo-de-germinacion-funciona-mejor", "area": "agricultura", "areas2": [], "titulo": "¿Qué método de germinación funciona mejor?", "resumen": "Prueba distintas formas de hacer germinar la misma semilla, como algodón húmedo, papel toalla, tierra directa y remojo previo, y compara cuántas brotan y cuánto tardan.", "tipo": "Análisis", "tiempo": "2 semanas", "horas": 12, "etiquetas": ["Germinación", "Semillas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Hay muchas recetas para germinar semillas y cada persona jura por la suya. Sin comparar con datos, es difícil saber cuál funciona mejor y cuál solo parece funcionar.", "Una prueba sencilla con el mismo tipo de semilla permite comparar métodos y no desperdiciar semillas valiosas."], "desarrollar": ["Elige una semilla comestible, como frijol, lenteja o rabanito, y prepara tres o cuatro métodos con el mismo número de semillas en cada uno, por ejemplo veinte. Rotula cada grupo y mantenlos a la misma temperatura.", "Cada día cuenta cuántas semillas germinaron y anota cuánto tardó cada método. Calcula el porcentaje de germinación y construye una gráfica para comparar."], "ampliaciones": [{"titulo": "Semillas viejas", "aporta": "repite la prueba con semillas de distintas edades."}, {"titulo": "Temperatura", "aporta": "prueba el mismo método en un lugar más cálido y otro más fresco."}, {"titulo": "Transplante", "aporta": "evalúa cuál germinó más fuerte al pasarlo a tierra."}], "objetivos": ["Preparar métodos comparables.", "Contar la germinación diaria.", "Calcular porcentajes.", "Recomendar un método."], "habilidades": ["Control de variables.", "Conteo y porcentajes.", "Gráficas.", "Paciencia y registro."], "herramientas": ["Semillas.", "Algodón, papel y tierra.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa semillas para cultivo, no semillas tratadas con químicos para otros fines.", "Lávate las manos después de manipular tierra o semillas."], "otroSector": "El mismo método de probar tasas de éxito sirve para comparar métodos de fabricación o de aprendizaje."}$a7agr$::jsonb,14),
('que-hace-que-un-huerto-domestico-produzca-mas-o-menos','agricultura',array['ambiente']::text[],'¿Qué hace que un huerto doméstico produzca más o menos?','Lleva el registro de un huerto casero y analiza qué factores se asocian con cosechar más: luz, riego, sustrato, tamaño de las macetas o cuidado, para saber dónde enfocar el esfuerzo.','Investigación','4 semanas',24,array['Productividad','Huerto doméstico']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura registro sistematico. analisis descriptivo. pensamiento critico. planificacion de mejoras. hoja de calculo. cuaderno de campo. camara del celular.',$a8agr${"id": "que-hace-que-un-huerto-domestico-produzca-mas-o-menos", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué hace que un huerto doméstico produzca más o menos?", "resumen": "Lleva el registro de un huerto casero y analiza qué factores se asocian con cosechar más: luz, riego, sustrato, tamaño de las macetas o cuidado, para saber dónde enfocar el esfuerzo.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Productividad", "Huerto doméstico"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Dos huertos del mismo tamaño pueden dar cosechas muy distintas. Quien cultiva suele echarle la culpa al clima o a la mala suerte, cuando muchas veces influyen cosas que sí se pueden ajustar.", "Registrar lo que se hace y lo que se cosecha permite descubrir patrones y mejorar la siguiente siembra."], "desarrollar": ["Durante unas semanas, anota para cada maceta de tu huerto, o de uno que conozcas con permiso, qué planta tiene, cuánta luz recibe, cuánto la riegas, qué sustrato lleva y cuánto cosechas o cuánto crece.", "Ordena los datos en una tabla y busca qué factores coinciden con mejores resultados. Elabora una lista de tres cambios que harías en la próxima siembra y por qué."], "ampliaciones": [{"titulo": "Comparar huertos", "aporta": "compara tu registro con el de otras personas, con permiso y de forma anónima."}, {"titulo": "Costo y producción", "aporta": "calcula cuánto produjo cada maceta en relación con lo que costó."}, {"titulo": "Predicción", "aporta": "usa tus datos para estimar cuánto cosecharías en la siguiente siembra."}], "objetivos": ["Registrar datos del huerto.", "Identificar patrones.", "Proponer ajustes.", "Comunicar los hallazgos."], "habilidades": ["Registro sistemático.", "Análisis descriptivo.", "Pensamiento crítico.", "Planificación de mejoras."], "herramientas": ["Hoja de cálculo.", "Cuaderno de campo.", "Cámara del celular."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No compares tu huerto con otros de forma que se identifique a quienes los cuidan.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro."], "otroSector": "El mismo análisis de factores sirve para entender por qué un puesto, una tienda o un equipo rinde más que otro."}$a8agr$::jsonb,15),
('un-huerto-que-produzca-durante-todo-el-ano','agricultura',array[]::text[],'Un huerto que produzca durante todo el año','Planifica un huerto pequeño para que siempre haya algo que cosechar, combinando cultivos de ciclos cortos y largos según el clima de tu zona y la época del año.','Plan','3 semanas',18,array['Producción continua','Planificación']::text[],array['crear','resolver']::text[],'publicos',NULL,'agronomia ingenieria ambiental geografia estadistica ciencia de datos ingenieria agricola fisica ingenieria de sistemas planificacion. lectura de datos climaticos. cronogramas. estimacion. datos publicos de clima. hoja de calculo. un editor de calendarios.',$a9agr${"id": "un-huerto-que-produzca-durante-todo-el-ano", "area": "agricultura", "areas2": [], "titulo": "Un huerto que produzca durante todo el año", "resumen": "Planifica un huerto pequeño para que siempre haya algo que cosechar, combinando cultivos de ciclos cortos y largos según el clima de tu zona y la época del año.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Producción continua", "Planificación"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Ingeniería Ambiental", "Geografía", "Estadística", "Ciencia de Datos", "Ingeniería Agrícola", "Física", "Ingeniería de Sistemas"], "problema": ["Muchos huertos dan todo de golpe y luego quedan vacíos durante meses. Cuando todo se siembra junto, se cosecha junto, y gran parte se pierde o se regala por no poder consumirlo.", "Escalonar las siembras permite tener cosechas más constantes y aprovechar mejor el espacio."], "desarrollar": ["Con datos públicos de clima de tu zona, identifica los meses más cálidos y más fríos. Elige cultivos de ciclo corto y de ciclo largo, anota en cuántas semanas se cosechan y sus meses recomendados de siembra.", "Arma un cronograma de doce meses que muestre cuándo sembrar y cuándo cosechar cada cultivo, de modo que no coincidan todas las cosechas. Resume el plan en una tabla y un calendario visual."], "ampliaciones": [{"titulo": "Por zona", "aporta": "adapta el plan a otra zona climática y compara las diferencias."}, {"titulo": "Rotación", "aporta": "incluye una rotación de cultivos para no cansar el suelo."}, {"titulo": "Cuánto sale", "aporta": "estima cuántas porciones podría dar el huerto cada mes."}], "objetivos": ["Identificar los ciclos de cada cultivo.", "Escalonar las siembras.", "Construir un calendario anual.", "Estimar las cosechas."], "habilidades": ["Planificación.", "Lectura de datos climáticos.", "Cronogramas.", "Estimación."], "herramientas": ["Datos públicos de clima.", "Hoja de cálculo.", "Un editor de calendarios."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Aclara que el plan es una guía general y que las fechas dependen del clima de cada año."], "otroSector": "La misma lógica de escalonar sirve para planificar la producción de cualquier negocio con demanda estacional."}$a9agr$::jsonb,16),
('un-huerto-escolar-diseno-y-plan-de-cuidado','agricultura',array['educacion']::text[],'Un huerto escolar: diseño y plan de cuidado','Diseña un huerto para un colegio o institución, con espacios, cultivos, responsables y turnos de cuidado, pensando en que funcione incluso en vacaciones y en que los estudiantes aprendan haciendo.','Plan','4 semanas',22,array['Huerto escolar','Cuidado compartido']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion agronomia biologia ingenieria ambiental trabajo social nutricion psicologia diseno planificacion de proyectos. organizacion de equipos. diseno de actividades. evaluacion. hoja de calculo. plano sencillo. un documento de plan.',$a10agr${"id": "un-huerto-escolar-diseno-y-plan-de-cuidado", "area": "agricultura", "areas2": ["educacion"], "titulo": "Un huerto escolar: diseño y plan de cuidado", "resumen": "Diseña un huerto para un colegio o institución, con espacios, cultivos, responsables y turnos de cuidado, pensando en que funcione incluso en vacaciones y en que los estudiantes aprendan haciendo.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Huerto escolar", "Cuidado compartido"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Agronomía", "Biología", "Ingeniería Ambiental", "Trabajo Social", "Nutrición", "Psicología", "Diseño"], "problema": ["Un huerto escolar empieza con entusiasmo y suele apagarse: las plantas se secan en vacaciones, nadie sabe quién riega y los materiales desaparecen. La falta de un plan de cuidado hace que muchos proyectos bonitos no duren.", "Diseñar quién hace qué, cuándo y con qué ayuda aumenta las posibilidades de que el huerto se mantenga."], "desarrollar": ["Imagina un colegio y elige un espacio posible para el huerto. Decide qué cultivos de ciclo corto conviene sembrar, cómo se organizarán los grupos y qué tareas habrá: regar, desmalezar, cosechar y registrar.", "Crea un calendario de turnos, un plan para las vacaciones y una lista de materiales. Incluye una actividad de aprendizaje por mes y un modo sencillo de evaluar si el huerto funciona."], "ampliaciones": [{"titulo": "Presupuesto", "aporta": "calcula cuánto costaría y cómo se financiaría."}, {"titulo": "Vacaciones", "aporta": "diseña un sistema de riego o un plan de apoyo para las semanas sin clases."}, {"titulo": "Cosecha", "aporta": "propón qué hacer con lo que se coseche sin que se desperdicie."}], "objetivos": ["Elegir espacio y cultivos.", "Organizar responsables y turnos.", "Diseñar actividades de aprendizaje.", "Plantear cómo evaluar el huerto."], "habilidades": ["Planificación de proyectos.", "Organización de equipos.", "Diseño de actividades.", "Evaluación."], "herramientas": ["Hoja de cálculo.", "Plano sencillo.", "Un documento de plan."], "lineamientos": ["Si trabajas con niñas y niños o con un colegio, hazlo con autorización de la institución y de las familias, sin fotos ni datos personales.", "Usa un colegio imaginario o el tuyo con permiso de la dirección, y no incluyas datos de estudiantes.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro."], "otroSector": "El mismo plan de turnos y responsables sirve para mantener cualquier espacio compartido, como un taller o un laboratorio."}$a10agr$::jsonb,17),
('como-organizar-un-huerto-comunitario','agricultura',array['sociedad']::text[],'Cómo organizar un huerto comunitario','Plantea cómo organizar un huerto compartido entre vecinos: acuerdos, reparto de tareas, uso del agua, qué hacer con la cosecha y cómo resolver desacuerdos para que dure en el tiempo.','Plan','3 semanas',20,array['Huerto comunitario','Organización vecinal']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia agronomia educacion administracion gestion de proyectos ingenieria ambiental comunicaciones organizacion comunitaria. redaccion de acuerdos. planificacion. negociacion. documento de acuerdo. hoja de calculo. un calendario compartido.',$a11agr${"id": "como-organizar-un-huerto-comunitario", "area": "agricultura", "areas2": ["sociedad"], "titulo": "Cómo organizar un huerto comunitario", "resumen": "Plantea cómo organizar un huerto compartido entre vecinos: acuerdos, reparto de tareas, uso del agua, qué hacer con la cosecha y cómo resolver desacuerdos para que dure en el tiempo.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Huerto comunitario", "Organización vecinal"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Agronomía", "Educación", "Administración", "Gestión de Proyectos", "Ingeniería Ambiental", "Comunicaciones"], "problema": ["Un huerto compartido puede unir a un barrio, pero también generar conflictos: alguien siempre riega más que otros, no se sabe cómo repartir la cosecha o hay desacuerdos sobre qué sembrar. Sin reglas claras, la motivación se pierde.", "Diseñar la organización antes de sembrar ayuda a que todos sepan qué se espera y cómo se decide."], "desarrollar": ["Imagina un grupo de vecinos o de compañeros y define quiénes participan, cuántas horas aporta cada uno y qué reglas de convivencia hacen falta. Decide cómo se reparten las parcelas o las tareas y cómo se usa el agua.", "Redacta un acuerdo simple de funcionamiento con reglas claras, un calendario de tareas y un modo de repartir la cosecha. Añade cómo se resolverían los desacuerdos y cómo se evaluaría el huerto después de tres meses."], "ampliaciones": [{"titulo": "Reglas del grupo", "aporta": "escribe un reglamento sencillo y compártelo para recibir comentarios."}, {"titulo": "Aportes", "aporta": "diseña un sistema para registrar quién aporta tiempo o materiales."}, {"titulo": "Cosecha", "aporta": "propón formas de repartir o aprovechar lo cosechado."}], "objetivos": ["Definir roles y acuerdos.", "Planificar tareas y agua.", "Repartir la cosecha.", "Prever cómo resolver desacuerdos."], "habilidades": ["Organización comunitaria.", "Redacción de acuerdos.", "Planificación.", "Negociación."], "herramientas": ["Documento de acuerdo.", "Hoja de cálculo.", "Un calendario compartido."], "lineamientos": ["Trabaja con casos inventados o con un grupo que te dé permiso, sin nombres ni datos personales.", "Ten en cuenta que cada comunidad tiene sus propias costumbres: propón, no impongas.", "Verifica con la autoridad local si necesitas permisos para usar un terreno."], "otroSector": "El mismo marco de acuerdos y turnos sirve para organizar cualquier espacio o recurso compartido entre vecinos o compañeros."}$a11agr$::jsonb,18)
